import json
import os
from generator.validator import ContentValidator

def build_vatandaslik_dataset():
    topics = []
    quick_notes = []
    questions = []

    def add_vat_bundle(t_id, title, slug, weight, order, note_title, note_content, note_ref, q_list):
        topics.append({
            "id": t_id,
            "course_id": "course-vatandaslik",
            "parent_id": None,
            "title": title,
            "slug": slug,
            "importance_weight": weight,
            "sort_order": order
        })
        quick_notes.append({
            "id": f"note-{t_id}",
            "topic_id": t_id,
            "title": note_title,
            "content": note_content,
            "source_reference": note_ref,
            "is_verified": True,
            "read_time_seconds": 45
        })
        for q in q_list:
            q["topic_id"] = t_id
            valid, errs = ContentValidator.validate_question(q)
            if not valid:
                raise ValueError(f"Vatandaşlık Soru Hatası ({q['id']}): {errs}")
            questions.append(q)

